/**
 * Curated Money Tips library. Every tip here is written and reviewed by a
 * person, not generated by Gemini - the AI provider is never involved in
 * choosing or wording these. Every fact/figure is sourced from an official
 * UK public body (GOV.UK, the Student Loans Company via GOV.UK, or
 * MoneyHelper - the free, impartial guidance service run by the
 * government's Money and Pensions Service). No blogs, no invented
 * statistics. URLs were verified against the live page when this file was
 * last reviewed - see `lastVerified` on each tip.
 */

export type TipCategory = "student_finance" | "budgeting" | "borrowing" | "loan_repayment";

/** Deterministic situations the dashboard can detect from real stored data - never inferred by the AI. */
export type TipTrigger =
  | "no_income_known"
  | "funding_award_schedule_unknown"
  | "shortfall_projected"
  | "loan_tracker_view";

export interface MoneyTip {
  id: string;
  title: string;
  body: string;
  category: TipCategory;
  sourceLabel: string;
  sourceUrl: string;
  /** When set, this tip is only eligible when the matching condition is detected. Undefined = general/rotating tip. */
  trigger?: TipTrigger;
  /** Higher = shown first among eligible tips. */
  priority: number;
  lastVerified: string;
}

